def __init__(self, dbname):
    """Set up a connection to the state DB."""
    try:
        self.conn = sqlite3.connect(dbname)
        self.cursor = self.conn.cursor()
        self._create_table()
    except sqlite3.Error:
        raise threatingestor.exceptions.IngestorError("State database seems broken")

def list_view(table):
    cursor.execute('SELECT name FROM sqlite_master WHERE type="table"')
    tables = [e[0] for e in cursor.fetchall()]

    if table == 'index':
        return tables

    elif table and table in tables:
        cursor.execute(f'SELECT * FROM {table}')

        data = []
        columns = [c[0] for c in cursor.description]
        for row in cursor.fetchall():
            data.append({k: v for k, v in zip(columns, row)})

        return data

    elif table:
        return f"No table {table}"

    else:
        return tables

def artifact_types(artifact_list):
    """Return a dictionary with counts of each artifact type."""
    types = {}
    for artifact in artifact_list:
        artifact_type = artifact.__class__.__name__.lower()
        if artifact_type in types:
            types[artifact_type] += 1
        else:
            types[artifact_type] = 1

    return types

