def _artifact_is_allowed(self, artifact):
    """Returns True iff this artifact is allowed by this plugin's filters."""
    # Must be in allowed_types.
    if not any(isinstance(artifact, t) for t in self.artifact_types):
        return False

    # Must match the filter string.
    if not artifact.match(self.filter_string):
        return False

    # Must be in allowed_sources, if set.
    if self.allowed_sources and not any(
            [re.compile(p).search(artifact.source_name)
             for p in self.allowed_sources]):
        return False

    return True

def process(self, artifacts):
    """Process all applicable artifacts."""
    for artifact in artifacts:
        if self._artifact_is_allowed(artifact):
            self.handle_artifact(artifact)

def _find_or_create_event(self, artifact):
    """Find or create an event for the artifact."""
    event = self._find_event(artifact)
    if event is not None:
        return event

    return self._create_event(artifact)

def _create_event(self, artifact):
    """Create an event in MISP, return an Event object."""
    event = pymisp.MISPEvent()
    event.info = self.event_info.format(source_name=artifact.source_name)

    # Add tags.
    for tag in self.tags:
        event.add_tag(tag)

    # Add references.
    if artifact.reference_link != "":
        event.add_attribute("link", artifact.reference_link)
    if artifact.reference_text != "":
        event.add_attribute("text", artifact.reference_text)
    if artifact.source_name != "":
        event.add_attribute("other",  f'source:{artifact.source_name}')

    return event

def run(self, saved_state):
    # Initialize.
    new_hash = saved_state
    all_filenames = []

    if saved_state:
        # Pull and diff to get filenames.
        try:
            _git_pull(self.local_path)
            new_hash = _git_latest_hash(self.local_path)
            all_filenames = _git_diff_names(self.local_path, saved_state).splitlines()
        except (OSError, subprocess.CalledProcessError):
            logger.exception(f"Error with git pull from '{self.local_path}'")

    else:
        # First run, we try cloning the repo and look at all files.
        try:
            _git_clone(self.url, self.local_path)
            new_hash = _git_latest_hash(self.local_path)
            all_filenames = _git_ls_files(self.local_path).splitlines()

        except subprocess.CalledProcessError:
            # Clone failed, maybe the repo already exists?
            # If so, update the saved state so we can pull on the next run.
            try:
                new_hash = _git_latest_hash(self.local_path)

            except (OSError, subprocess.CalledProcessError):
                # That also failed, so this is just a generic error.
                logger.exception(f"Error with git clone of '{self.url}' to '{self.local_path}'")

        except OSError:
            logger.exception(f"Error with git clone of '{self.url}' to '{self.local_path}'")

    # If not modified or any errors, return immediately.
    if saved_state == new_hash:
        return saved_state, []

    # Otherwise, process YARA files.
    artifact_list = []
    for filename in all_filenames:
        if any([filename.endswith(x) for x in YARA_FILE_EXTS]):
            try:
                with io.open(os.path.join(self.local_path, filename), 'r', encoding='utf-8', errors='ignore') as f:
                    artifact_list += self.process_element(f.read(), self.url, include_nonobfuscated=True)
            except OSError:
                # The file was most likely deleted.
                pass

    return new_hash, artifact_list

def _git_cmd(args):
    """Call a git command.

    :raises: subprocess.CalledProcessError
    """
    git_cmdline = ['git'] + args
    return subprocess.check_output(git_cmdline).decode('utf-8')

