def run(self, saved_state):
    """Run and return (saved_state, list(Artifact))"""
    artifact_list = []

    saved_state, content_list = self.get_objects(saved_state)
    for content in content_list:
        # Iterate over each piece of "content", extracting from every path of interest.
        for path_expression in self.path_expressions:
            matches = path_expression.find(content)

            # Try to get a single reference, fall back to name again.
            try:
                reference = self.reference.find(content)[0].value
            except (IndexError, AttributeError):
                reference = self.name

            # Extract artifacts.
            for match in matches:
                artifact_list += self.process_element(match.value, reference, include_nonobfuscated=True)

    return saved_state, artifact_list

def __init__(self, name, url):
    self.name = name
    self.url = url

def run(self, saved_state):
    # Modify kwargs to insert since_id.
    if saved_state:
        self.kwargs['since_id'] = saved_state

    artifacts = []

    def bearer_oauth2(r):
        r.headers['Authorization'] = f"Bearer {self.bearer_token}"
        r.headers['User-Agent'] = "InQuestThreatIngestor"
        return r

    if self.kwargs.get('list_id'):
        list_url = f"https://api.twitter.com/2/lists/{self.kwargs.get('list_id')}/tweets"
        self.endpoint = requests.get(url=list_url, auth=bearer_oauth2, params="tweet.fields=lang,author_id")

        for tweet in self.endpoint.json()['data']:
            artifacts += self.process_element(content=tweet['text'], reference_link=tweet['id'], include_nonobfuscated=self.include_nonobfuscated)

    if self.kwargs.get('username') or self.kwargs.get('user_id'):
        try:
            # Get the id of the username
            user_id = self.kwargs.get('user_id') or self.auth['OAuth2'].users.by.username._username(_username=self.kwargs.get('username'))["data"]["id"]
            self.endpoint = self.auth['OAuth2'].users._id.tweets(_id=user_id)
        except twitter.api.TwitterHTTPError as e:
            # API error; log and return early
            logger.warning(f"Twitter API Error: {e}")
            return saved_state, []

        for tweet in self.endpoint['data']:
            saved_state = tweet['id']
            artifacts += self.process_element(content=tweet['text'], reference_link=tweet['id'], include_nonobfuscated=self.include_nonobfuscated)

    if self.kwargs.get('query'):
        try:
            self.endpoint = self.auth['OAuth2'].tweets.search.recent(query=self.kwargs.get('query'))
        except twitter.api.TwitterHTTPError as e:
            # API error; log and return early
            logger.warning(f"Twitter API Error: {e}")
            return saved_state, []

        for tweet in self.endpoint['data']:
            saved_state = tweet['id']
            artifacts += self.process_element(content=tweet['text'], reference_link=tweet['id'], include_nonobfuscated=self.include_nonobfuscated)

    # No endpoint specified, return early
    if not self.endpoint:
        return saved_state, []

    return saved_state, artifacts

def _repository_search(self, params):
    """Returns a list of repository results."""

    # Iterates through pages of results from query.
    response = requests.get(REPO_SEARCH_URL, params=params, auth=self.auth)

    repo_list = []

    while True:
        for repo in response.json().get('items', []):
            repo_list.append(repo)

        if not response.links.get('next'):
            break

        response = requests.get(
            response.links.get('next')["url"], auth=self.auth)

    return repo_list

def do_work(self, job):
    """
    From a paste URL, get the raw contents.
    """

    try:
        url = job['url']
    except KeyError:
        print(f"Bad job: {job}")
        return

    # Pastebin.com
    if url.startswith("https://pastebin.com/raw/"):
        pass

    elif url.startswith("https://pastebin.com/"):
        start, end = url.split['.com/']
        url = '.com/raw/'.join([start, end])

    # Gist
    elif url.startswith("https://gist.github.com/") and not 'raw' in url:
        url = url + '/raw'

    # Fetch and return
    response = requests.get(url)

    return {
        'content': response.content,
        'reference': response.url,
    }
